import sys
sys.path.append('storage/ariadne')

import optax
import jax.numpy as jnp
from models_fourier import FourierForecasterLNV3Generic
from models import ResidualCopyHead
from losses import mae_with_temporal_curvature

BASE_SEED = 42
BATCH_SIZE = 8

class Wrapper:
    def __init__(self, rank_k=320, proj_rank=36, num_harmonics=16, hidden_size=192, mlp_depth=2,
                 gamma_start=0.25, gamma_end=0.99, ln_in_factor=True):
        self.backbone = FourierForecasterLNV3Generic(
            rank_k=rank_k, proj_rank=proj_rank, num_harmonics=num_harmonics,
            hidden_size=hidden_size, mlp_depth=mlp_depth,
            gamma_start=gamma_start, gamma_end=gamma_end, ln_in_factor=ln_in_factor
        )
        self.copy_head = ResidualCopyHead(output_horizon=32)
        self.needs_rng = False
    def init(self, rng_key, dummy_input):
        params_back = self.backbone.init(rng_key, dummy_input, training=True)
        return {"backbone": params_back, "copy": {}}
    def apply(self, params, x, training=False, mutable=None, rngs=None):
        y_factor = self.backbone.apply(params["backbone"], x, training=training)
        y_copy = self.copy_head(x)
        return y_factor + y_copy

def _define_hyperparameters():
    return {
        "learning_rate": 9e-4,
        "rank_k": 320,
        "proj_rank": 36,
        "num_harmonics": 16,
        "hidden_size": 192,
        "mlp_depth": 2,
        "gamma_start": 0.25,
        "gamma_end": 0.99,
        "ln_in_factor": True
    }

def create_network(hparams):
    return Wrapper(
        rank_k=int(hparams.get("rank_k", 320)),
        proj_rank=int(hparams.get("proj_rank", 36)),
        num_harmonics=int(hparams.get("num_harmonics", 16)),
        hidden_size=int(hparams.get("hidden_size", 192)),
        mlp_depth=int(hparams.get("mlp_depth", 2)),
        gamma_start=float(hparams.get("gamma_start", 0.25)),
        gamma_end=float(hparams.get("gamma_end", 0.99)),
        ln_in_factor=bool(hparams.get("ln_in_factor", True))
    )

def compute_loss(predictions, targets, params, x):
    return mae_with_temporal_curvature(predictions, targets, params, x, lam=1e-4)

def create_optimizer(learning_rate: float = 0.001):
    return optax.chain(
        optax.clip_by_global_norm(1.0),
        optax.adam(learning_rate=9e-4, eps=1e-8)
    )
